#requires -Version 5.1
[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$TaskDirectory)
Set-StrictMode -Version 2.0
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$WarningPreference='SilentlyContinue'
# This private worker takes only a directory generated by task.start. It never
# reads commands from the public transport and writes no transport output.
function Stop-Dev([string]$Code,[string]$Message) {throw $Code}
$workerRoot=$PSScriptRoot
$runner=$null;$state=$null;$phase='load_module';$receipt=$null
try {
    . (Join-Path (Split-Path $workerRoot -Parent) 'tasks.ps1')
    $phase='read_request'
    $request=Read-TaskJson (Join-Path $TaskDirectory 'request.json')
    $timer=[Diagnostics.Stopwatch]::StartNew()
    $receiptPath=Join-Path $TaskDirectory 'receipt.json'
    while (![IO.File]::Exists($receiptPath)) {if ($timer.ElapsedMilliseconds -gt 5000) {throw 'Worker receipt unavailable.'};Start-Sleep -Milliseconds 25}
    $receipt=Read-TaskJson $receiptPath
    $state=[ordered]@{task_id=$receipt.task_id;profile=$receipt.profile;status='starting';created_at=$receipt.created_at;pid=$null;start_time_utc=$null;exit_code=$null;stdout_truncated=$false;stderr_truncated=$false}
    Write-TaskJson (Join-Path $TaskDirectory 'state.json') $state
    $phase='load_native'
    Add-Type -Path (Join-Path $workerRoot 'task-native.cs')
    $environment=New-Object 'Collections.Generic.Dictionary[string,string]' ([StringComparer]::OrdinalIgnoreCase)
    foreach($property in $request.env.PSObject.Properties){$environment[$property.Name]=[string]$property.Value}
    $runner=New-Object Starbridge.Developer.TaskProcess
    $phase='launch'
    $runner.Start($request.executable,[string[]]$request.args,$request.cwd,$environment,(Join-Path $TaskDirectory 'stdout.bin'),(Join-Path $TaskDirectory 'stderr.bin'),[int]$request.max_output_bytes,[bool]$request.show_window)
    $requestPath=Join-Path $TaskDirectory 'request.json'
    if([IO.File]::Exists($requestPath)){[IO.File]::Delete($requestPath)}
    $phase='monitor'
    $state.status='running';$state.pid=$runner.Pid;$state.start_time_utc=(New-Object DateTime($runner.StartTimeTicks,[DateTimeKind]::Utc)).ToString('o')
    $state['process_identity']=[ordered]@{pid=$runner.Pid;start_ticks=$runner.StartTimeTicks;executable=$runner.Executable}
    Write-TaskJson (Join-Path $TaskDirectory 'state.json') $state
    $timer.Restart();$reason='exited'
    while (!$runner.IsComplete) {
        foreach($file in @(Get-ChildItem -LiteralPath $TaskDirectory -Filter 'control-*.json' -File)) {
            $control=Read-TaskJson $file.FullName;$answer=[ordered]@{accepted=$false;control_status='blocked';reason='UNSUPPORTED_CONTROL'}
            if ($control.action -ceq 'cancel') {$runner.Cancel();$reason='cancelled';$state.status='cancelling';$answer=[ordered]@{accepted=$true;control_status='accepted'}}
            elseif ($control.action -ceq 'close') {
                $accepted=$false
                try {$accepted=$runner.RequestClose()} catch { }
                if($accepted){$state.status='closing';$answer=[ordered]@{accepted=$true;control_status='accepted'}}
                else {$answer.reason='NO_MAIN_WINDOW_OR_CLOSE_BLOCKED'}
            }
            Write-TaskJson (Join-Path $TaskDirectory ($file.Name.Replace('control-','answer-'))) $answer
            [IO.File]::Delete($file.FullName)
        }
        if($timer.ElapsedMilliseconds -ge [long]$request.timeout_ms){$runner.Cancel();$reason='timed_out'}
        $state.stdout_truncated=$runner.StdoutTruncated;$state.stderr_truncated=$runner.StderrTruncated
        Write-TaskJson (Join-Path $TaskDirectory 'state.json') $state
        Start-Sleep -Milliseconds 100
    }
    $runner.FinishOutput();$state.status=$reason;$state.exit_code=$runner.ExitCode
    $state.stdout_truncated=$runner.StdoutTruncated;$state.stderr_truncated=$runner.StderrTruncated
    Write-TaskJson (Join-Path $TaskDirectory 'state.json') $state
} catch {
    $failure=$_
    if($null -eq $state){
        # Module-load and request-read failures happen before the normal state
        # record. Record only safe fields, without requiring module helpers.
        try {
            $receiptPath=Join-Path $TaskDirectory 'receipt.json'
            $timer=[Diagnostics.Stopwatch]::StartNew()
            while(![IO.File]::Exists($receiptPath) -and $timer.ElapsedMilliseconds -lt 1000){Start-Sleep -Milliseconds 25}
            $receipt=ConvertFrom-Json -InputObject ([IO.File]::ReadAllText($receiptPath))
            $state=[ordered]@{task_id=$receipt.task_id;profile=$receipt.profile;status='failed';created_at=$receipt.created_at;pid=$null;start_time_utc=$null;exit_code=$null;stdout_truncated=$false;stderr_truncated=$false}
        }catch{}
    }
    if($null -ne $state){
        $state.status='failed';$state['error_code']='TASK_WORKER_FAILED';$state['failure_stage']=$phase
        $exception=$failure.Exception
        for($depth=0;$depth-lt8 -and $null-ne$exception.InnerException;$depth++){$exception=$exception.InnerException}
        $state['failure_exception_type']=$exception.GetType().Name
        $state['failure_line']=[int]$failure.InvocationInfo.ScriptLineNumber
        if($exception -is [ComponentModel.Win32Exception]){$state['failure_native_error']=[int]$exception.NativeErrorCode}
        if($null-ne$runner){$state['failure_native_stage']=[string]$runner.Stage}
        try {
            $statePath=Join-Path $TaskDirectory 'state.json'
            if($null-ne(Get-Command Write-TaskJson -ErrorAction SilentlyContinue)){Write-TaskJson $statePath $state}
            else{
                $temporary=$statePath+'.'+[Guid]::NewGuid().ToString('N')+'.tmp'
                [IO.File]::WriteAllText($temporary,(ConvertTo-Json -InputObject $state -Compress -Depth 12),(New-Object Text.UTF8Encoding($false)))
                if([IO.File]::Exists($statePath)){[IO.File]::Replace($temporary,$statePath,$null)}else{[IO.File]::Move($temporary,$statePath)}
            }
        }catch{}
    }
} finally {
    if($null -ne $runner){$runner.Dispose()}
    # The request can contain environment secrets. Keep only receipt, identities,
    # bounded output, and completion state after the worker has read it.
    $requestPath=Join-Path $TaskDirectory 'request.json'
    if([IO.File]::Exists($requestPath)){[IO.File]::Delete($requestPath)}
}
